using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class PruneOrphanTreePieces {public static object Main(){EditorApplication.delayCall+=()=>{try{var rows=new List<string>();foreach(var scene in Racer.RacePlaylists.Scenes){UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/"+scene+".unity");Physics.SyncTransforms();var cs=UnityEngine.Object.FindObjectsByType<Collider>().Where(c=>c.name.ToLower().Contains("tree")||c.name.ToLower().Contains("trunk")).ToArray();foreach(var mf in UnityEngine.Object.FindObjectsByType<MeshFilter>().Where(m=>m.GetComponent<Renderer>()&&m.GetComponent<Renderer>().sharedMaterial&&m.GetComponent<Renderer>().sharedMaterial.name=="Forest")){var v=mf.sharedMesh.vertices;var ts=mf.sharedMesh.triangles;var used=ts.Distinct().ToArray();var parents=Enumerable.Range(0,v.Length).ToArray();int F(int i){while(parents[i]!=i){parents[i]=parents[parents[i]];i=parents[i];}return i;}void J(int a,int b){parents[F(a)]=F(b);}var weld=new Dictionary<Vector3Int,int>();foreach(int i in used){var key=Vector3Int.RoundToInt(v[i]*1000);if(weld.TryGetValue(key,out int o))J(i,o);else weld[key]=i;}for(int i=0;i<ts.Length;i+=3){J(ts[i],ts[i+1]);J(ts[i],ts[i+2]);}var cuts=new HashSet<int>();foreach(var g in used.GroupBy(F)){var b=new Bounds(mf.transform.TransformPoint(v[g.First()]),Vector3.zero);foreach(int i in g)b.Encapsulate(mf.transform.TransformPoint(v[i]));var p=b.center;var axis=new Vector3(.35f,0,1).normalized;var delta=p-new Vector3(334.05f,0,-212);bool water=p.x>355&&p.x<435&&p.z>-217&&p.z<-175;bool home=Vector2.Distance(new(p.x,p.z),new(370.3f,12.7f))<65;bool roger=Vector2.Distance(new(p.x,p.z),new(440,-82))<28;bool ramp=scene=="StreetLoopReverse"&&Vector3.Dot(delta,axis)>-45&&Vector3.Dot(delta,axis)<103&&Math.Abs(Vector3.Dot(delta,Vector3.Cross(Vector3.up,axis)))<13&&p.y>55;if(!water&&!home&&!roger&&!ramp)continue;var c=cs.OrderBy(c=>Vector2.Distance(new(c.bounds.center.x,c.bounds.center.z),new(b.center.x,b.center.z))).First();float d=Vector2.Distance(new(c.bounds.center.x,c.bounds.center.z),new(b.center.x,b.center.z));if(d>6){cuts.Add(g.Key);rows.Add(scene+" removed orphan render piece "+mf.name+" "+b+" nearest current trunk="+d);}}if(cuts.Count>0){var copy=UnityEngine.Object.Instantiate(mf.sharedMesh);var keep=new List<int>();for(int i=0;i<ts.Length;i+=3)if(!cuts.Contains(F(ts[i])))keep.AddRange(new[]{ts[i],ts[i+1],ts[i+2]});copy.triangles=keep.ToArray();copy.RecalculateBounds();AssetDatabase.CreateAsset(copy,AssetDatabase.GenerateUniqueAssetPath("Assets/Track/BackyardReverse/OrphanCleanup-"+scene+".asset"));mf.sharedMesh=copy;}}UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());AssetDatabase.SaveAssets();}File.WriteAllLines("Docs/BackyardReverse/orphan-piece-cleanup.txt",rows);File.WriteAllText("Docs/BackyardReverse/orphan-done.txt","Scoped orphan crown cleanup complete");}catch(Exception e){File.WriteAllText("Docs/BackyardReverse/orphan-error.txt",e.ToString());}};return "Remove existing orphan crowns only in affected vegetation regions";}}

